const header=document.querySelector('header');const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('nav');function updateHeader(){header.classList.toggle('solid',window.scrollY>30)}window.addEventListener('scroll',updateHeader,{passive:true});updateHeader();menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');nav.querySelectorAll('details').forEach(d=>d.open=false)}));
const projectDialog=document.querySelector('#project-dialog');document.querySelectorAll('.project-open').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#project-title').textContent=button.dataset.country;document.querySelector('#project-service').textContent=button.dataset.service;projectDialog.showModal()}));document.querySelector('#credits-open').addEventListener('click',()=>document.querySelector('#credits-dialog').showModal());document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}})});if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.about-grid,.section-heading,.service,.project').forEach(element=>{element.classList.add('reveal');observer.observe(element)})}
